from decimal import Decimal, getcontext, ROUND_HALF_UP, ROUND_DOWN, InvalidOperation

getcontext().prec = 80

_Q2 = Decimal("0.01")

# Valores por defecto tomados de src/02_parametros.sql (LS_PARAMETROS)
_DEFAULT_PARAMS = {
    "DIAS_MAX_DENUNCIA": Decimal("30"),
    "DIAS_MAX_DENUNCIA_VIDA": Decimal("365"),
    "DEDUCIBLE_MINIMO": Decimal("100"),
    "PCT_DESCUENTO_DED_VIP": Decimal("50"),
    "TOLERANCIA_MORA_VIP": Decimal("500"),
    "MAX_SINIESTROS_ANUAL": Decimal("3"),
    "PCT_PENALIZACION_SINIEST": Decimal("10"),
    "UMBRAL_RETENCION": Decimal("10000"),
    "TASA_RETENCION": Decimal("2"),
    "TOPE_AUTO_APROBACION": Decimal("50000"),
    "DIAS_ALERTA_FRAUDE": Decimal("15"),
    "PCT_ALERTA_FRAUDE": Decimal("80"),
    "FACTOR_INFLACION": Decimal("1.035"),
    "TASA_IVA": Decimal("19"),
}

# Alias tolerados (por si el arnés usa nombres en inglés)
_ALIASES = {
    "MAX_REPORT_DAYS": "DIAS_MAX_DENUNCIA",
    "MAX_REPORT_DAYS_LIFE": "DIAS_MAX_DENUNCIA_VIDA",
    "MIN_DEDUCTIBLE": "DEDUCIBLE_MINIMO",
    "VIP_DEDUCTIBLE_DISCOUNT_PCT": "PCT_DESCUENTO_DED_VIP",
    "VIP_ARREARS_TOLERANCE": "TOLERANCIA_MORA_VIP",
    "MAX_ANNUAL_CLAIMS": "MAX_SINIESTROS_ANUAL",
    "CLAIMS_PENALTY_PCT": "PCT_PENALIZACION_SINIEST",
    "WITHHOLDING_THRESHOLD": "UMBRAL_RETENCION",
    "WITHHOLDING_RATE": "TASA_RETENCION",
    "AUTO_APPROVAL_CAP": "TOPE_AUTO_APROBACION",
    "FRAUD_ALERT_DAYS": "DIAS_ALERTA_FRAUDE",
    "FRAUD_ALERT_PCT": "PCT_ALERTA_FRAUDE",
    "INFLATION_FACTOR": "FACTOR_INFLACION",
    "VAT_RATE": "TASA_IVA",
}


class _OraError(Exception):
    def __init__(self, code):
        Exception.__init__(self, code)
        self.code = code


def _strip_q(s):
    s = s.strip()
    while len(s) >= 2 and s[0] in "\"'" and s[-1] in "\"'":
        s = s[1:-1].strip()
    return s


def _parse_params(text):
    params = dict(_DEFAULT_PARAMS)
    if text is None:
        return params
    t = str(text).strip()
    if not t:
        return params
    for ch in "{}[]":
        t = t.replace(ch, "")
    for sep in [";", "\n", "\r"]:
        t = t.replace(sep, ",")
    for item in t.split(","):
        item = item.strip()
        if not item:
            continue
        if ":" in item:
            k, v = item.split(":", 1)
        elif "=" in item:
            k, v = item.split("=", 1)
        else:
            continue
        k = _strip_q(k).upper()
        k = _ALIASES.get(k, k)
        v = _strip_q(v)
        if v == "" or v.lower() in ("null", "none"):
            continue
        try:
            params[k] = Decimal(v)
        except (InvalidOperation, ValueError):
            continue
    return params


def _dec(s, default="0"):
    if s is None:
        return Decimal(default)
    s = str(s).strip()
    if s == "":
        return Decimal(default)
    return Decimal(s)


def _r2(x):
    # ROUND(x, 2) de Oracle / asignacion a NUMBER(14,2): mitad hacia arriba
    return x.quantize(_Q2, rounding=ROUND_HALF_UP)


def _days(datestr):
    s = str(datestr).strip()[:10]
    y, m, d = int(s[0:4]), int(s[5:7]), int(s[8:10])
    # numero de dia absoluto (algoritmo civil -> dias)
    if m <= 2:
        y -= 1
    era = (y if y >= 0 else y - 399) // 400
    yoe = y - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe


def _bool(s):
    return str(s).strip().upper() in ("TRUE", "1", "S", "SI", "Y", "YES", "T")


def _fmt2(x):
    return str(_r2(Decimal(x)))


def run(inp: dict) -> dict:
    out = {
        "status": "",
        "reason_code": "",
        "base_amount": "0.00",
        "deductible_amount": "0.00",
        "covered_amount": "0.00",
        "withholding_amount": "0.00",
        "net_amount": "0.00",
        "observations": "",
        "error_code": "",
    }

    params = _parse_params(inp.get("business_parameters"))

    def p(code):
        if code not in params:
            raise _OraError("ORA-20010")
        return params[code]

    def reject(reason, obs=None):
        out["status"] = "RECHAZADA"
        out["reason_code"] = reason
        out["base_amount"] = "0.00"
        out["deductible_amount"] = "0.00"
        out["covered_amount"] = "0.00"
        out["withholding_amount"] = "0.00"
        out["net_amount"] = "0.00"
        out["observations"] = obs if obs else ""
        return out

    obs_list = []

    def add_obs(mark):
        obs_list.append(mark)

    def obs_text():
        return ";".join(obs_list) if obs_list else None

    try:
        claim_amount = _r2(_dec(inp.get("claim_amount")))
        occ = _days(inp.get("occurrence_date"))
        rep = _days(inp.get("report_date"))
        pol_status = str(inp.get("policy_status", "")).strip()
        branch = str(inp.get("policy_branch", "")).strip()
        pstart = _days(inp.get("policy_start_date"))
        pend = _days(inp.get("policy_end_date"))
        sum_insured = _r2(_dec(inp.get("sum_insured")))
        ded_type = str(inp.get("deductible_type", "")).strip()
        ded_value = _r2(_dec(inp.get("deductible_value")))
        pending_premium = _r2(_dec(inp.get("pending_premium")))
        category = str(inp.get("customer_category", "")).strip()
        cov_found = _bool(inp.get("coverage_found", ""))
        cov_limit = _r2(_dec(inp.get("coverage_limit")))
        cov_pct = _r2(_dec(inp.get("coverage_percentage")))
        waiting_days = _dec(inp.get("waiting_days")).to_integral_value(rounding=ROUND_HALF_UP)
        prior_claims = _dec(inp.get("prior_liquidated_claims_365d"))
        total_indemnified = _dec(inp.get("total_indemnified"))

        # Linea 375: se lee FACTOR_INFLACION al inicio (no se usa en el calculo)
        p("FACTOR_INFLACION")

        # 1.a Estado de la poliza
        if pol_status != "VIGENTE":
            return reject("POLIZA_NO_VIGENTE")

        # 1.b Vigencia (extremos inclusive)
        if occ < pstart or occ > pend:
            return reject("FUERA_DE_VIGENCIA")

        # 1.c Plazo de denuncia
        dias_denuncia = rep - occ
        if branch == "VIDA":
            dias_max = p("DIAS_MAX_DENUNCIA_VIDA")
        else:
            dias_max = p("DIAS_MAX_DENUNCIA")
        if Decimal(dias_denuncia) > dias_max:
            return reject("DENUNCIA_EXTEMPORANEA")

        # 1.d Cobertura contratada
        if not cov_found:
            return reject("COBERTURA_NO_CONTRATADA")

        # 1.e Carencia
        dias_desde_inicio = occ - pstart
        if Decimal(dias_desde_inicio) < waiting_days:
            return reject("EN_PERIODO_CARENCIA")

        # 1.f Morosidad
        if pending_premium > 0:
            tolerancia = p("TOLERANCIA_MORA_VIP")
            if category == "VIP" and pending_premium <= tolerancia:
                add_obs("TOLERANCIA_MORA_VIP")
            else:
                return reject("PRIMA_EN_MORA", obs_text())

        # 2.a Monto base
        if claim_amount > cov_limit:
            monto_base = _r2(cov_limit)
            add_obs("LIMITE_COBERTURA")
        else:
            monto_base = _r2(claim_amount)

        # 2.b Deducible (fn_calcular_deducible, v_deducible NUMBER(14,2))
        if ded_type == "FIJO":
            deducible = _r2(ded_value)
        else:
            ded_min = p("DEDUCIBLE_MINIMO")
            deducible = _r2(monto_base * ded_value / Decimal(100))
            if deducible < ded_min:
                deducible = _r2(ded_min)
                add_obs("DEDUCIBLE_MINIMO")
        if category == "VIP" and deducible > 0:
            pct_vip = p("PCT_DESCUENTO_DED_VIP")
            deducible = _r2(deducible * (Decimal(100) - pct_vip) / Decimal(100))
            add_obs("DESCUENTO_VIP")
        deducible = _r2(deducible)

        # 2.c Monto cubierto
        cubierto = _r2((monto_base - deducible) * cov_pct / Decimal(100))
        if cubierto <= 0:
            return reject("BAJO_DEDUCIBLE", obs_text())

        # 2.d Siniestralidad
        if prior_claims >= p("MAX_SINIESTROS_ANUAL"):
            cubierto = _r2(cubierto * (Decimal(100) - p("PCT_PENALIZACION_SINIEST")) / Decimal(100))
            add_obs("PENALIZACION_SINIESTRALIDAD")

        # 2.e Suma asegurada remanente
        remanente = sum_insured - total_indemnified
        if remanente <= 0:
            return reject("SUMA_ASEGURADA_AGOTADA", obs_text())
        if cubierto > remanente:
            cubierto = _r2(remanente)
            add_obs("TOPE_SUMA_ASEGURADA")

        # 2.f Retencion
        if branch != "VIDA" and cubierto > p("UMBRAL_RETENCION"):
            retencion = _r2(cubierto * p("TASA_RETENCION") / Decimal(100))
            add_obs("RETENCION_APLICADA")
        else:
            retencion = Decimal("0.00")

        neto = _r2(cubierto - retencion)

        # 3. Estado final
        umbral_fraude = _r2(cov_limit * p("PCT_ALERTA_FRAUDE") / Decimal(100))
        if Decimal(dias_desde_inicio) <= p("DIAS_ALERTA_FRAUDE") and claim_amount >= umbral_fraude:
            estado, motivo = "PENDIENTE_APROBACION", "SOSPECHA_FRAUDE"
        elif neto > p("TOPE_AUTO_APROBACION"):
            estado, motivo = "PENDIENTE_APROBACION", "SUPERA_TOPE_AUTOMATICO"
        else:
            estado, motivo = "APROBADA", "LIQUIDACION_AUTOMATICA"

        out["status"] = estado
        out["reason_code"] = motivo
        out["base_amount"] = _fmt2(monto_base)
        out["deductible_amount"] = _fmt2(deducible)
        out["covered_amount"] = _fmt2(cubierto)
        out["withholding_amount"] = _fmt2(retencion)
        out["net_amount"] = _fmt2(neto)
        out["observations"] = obs_text() or ""
        out["error_code"] = ""
        return out

    except _OraError as e:
        out["status"] = ""
        out["reason_code"] = ""
        out["base_amount"] = "0.00"
        out["deductible_amount"] = "0.00"
        out["covered_amount"] = "0.00"
        out["withholding_amount"] = "0.00"
        out["net_amount"] = "0.00"
        out["observations"] = ""
        out["error_code"] = e.code
        return out
